partG_example:
# Program demonstrating break, continue, and pass
print('Demonstrating break (stops at 3):')
for i in range(1, 6):
    if i == 3:
        break
    print(i, end=' ')
print()  # newline

print('Demonstrating continue (skips 3):')
for i in range(1, 6):
    if i == 3:
        continue
    print(i, end=' ')
print()  # newline

print('Demonstrating pass (placeholder):')
for i in range(1, 4):
    if i == 2:
        pass  # Placeholder, does nothing
    print(i, end=' ')
print()  # newline
